const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kabul = ee.Geometry.Point([69.2075, 34.5553]);
  const radius = 30 * 1609.34; // 30 miles to meters
  const geometry = kabul.buffer(radius);

  const date2017_start = '2017-02-01';
  const date2017_end = '2017-03-01';
  const date2018_start = '2018-02-01';
  const date2018_end = '2018-03-01';

  // 2. Data Acquisition
  const collection2017 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterBounds(geometry)
    .filterDate(date2017_start, date2017_end)
    .select('LST_Day_1km');

  const collection2018 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterBounds(geometry)
    .filterDate(date2018_start, date2018_end)
    .select('LST_Day_1km');

  const size2017 = await collection2017.size().getInfo();
  const size2018 = await collection2018.size().getInfo();

  console.log(`2017 Images: ${size2017}`);
  console.log(`2018 Images: ${size2018}`);

  if (size2017 === 0 || size2018 === 0) {
    console.log("No data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites
  const mean2017 = collection2017.mean();
  const mean2018 = collection2018.mean();

  // 4. Calculate statistics
  const stats2017 = await mean2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = await mean2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const temp2017_k = stats2017.LST_Day_1km_mean;
  const temp2018_k = stats2018.LST_Day_1km_mean;
  const count2017 = stats2017.LST_Day_1km_count;
  const count2018 = stats2018.LST_Day_1km_count;

  console.log(`2017 Valid Pixels: ${count2017}`);
  console.log(`2018 Valid Pixels: ${count2018}`);

  // Check for no valid pixels
  if (count2017 === 0 || count2018 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for null/undefined values
  if (temp2017_k == null || temp2018_k == null) {
    console.log("Calculation failed - null values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert from Kelvin to Celsius (MODIS LST scale factor 0.02)
  const temp2017_c = (temp2017_k * 0.02) - 273.15;
  const temp2018_c = (temp2018_k * 0.02) - 273.15;

  console.log(`2017 Mean Temp: ${temp2017_c.toFixed(2)}°C`);
  console.log(`2018 Mean Temp: ${temp2018_c.toFixed(2)}°C`);

  // Validate temperature ranges
  if (temp2017_c < -100 || temp2017_c > 100 || temp2018_c < -100 || temp2018_c > 100) {
    console.log("Temperature values out of valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final Answer
  const tempDiff = temp2018_c - temp2017_c;
  console.log(`Temperature Difference: ${tempDiff.toFixed(2)}°C`);

  if (temp2018_c > temp2017_c) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
